function CountPartitionsDistinct(n, maxPart)
    if n eq 0 then
        return 1;
    end if;
    if maxPart le 0 or n lt 0 then
        return 0;
    end if;
    return CountPartitionsDistinct(n - maxPart, maxPart - 1) + CountPartitionsDistinct(n, maxPart - 1);
end function;

