function CountDistinctPartitions(n)
    count := 0;
    // Iterate through all 2^n subsets of {1, 2, ..., n}
    for mask in [0..2^n-1] do
        sum := 0;
        for i in [1..n] do
            if (mask div (2^(i-1))) mod 2 eq 1 then
                sum +:= i;
            end if;
        end for;
        if sum eq n then
            count +:= 1;
        end if;
    end for;
    return count;
end function;

print CountDistinctPartitions(20);

function CountPartitionsDistinct(n, maxPart, memo)
    if n eq 0 then
        return 1;
    end if;
    if n lt 0 then
        return 0;
    end if;
    if maxPart eq 0 then
        return 0;
    end if;

    key := <n, maxPart>;
    if IsDefined(memo, key) then
        return memo[key];
    end if;

    // Either include maxPart or don't
    with := CountPartitionsDistinct(n - maxPart, maxPart - 1, memo);
    without := CountPartitionsDistinct(n, maxPart - 1, memo);

    result := with + without;
    memo[key] := result;
    return result;
end function;

