// Count partitions of 20 into distinct parts using dynamic programming
// DP state: (remaining_sum, max_part_allowed)
// We count ways to partition remaining_sum using only parts at most max_part_allowed

function CountDP(n, max_part, memo)
  // Create string key for memoization
  key := Sprintf("%o,%o", n, max_part);

  if IsDefined(memo, key) then
    return memo[key];
  end if;

  if (n eq 0) then
    result := 1;  // One way: the empty partition
  else
    if (n lt 0) then
      result := 0;
    else
      if (max_part eq 0) then
        result := 0;
      else
        // Either include max_part (if possible) or skip it
        // If we include max_part, we need to partition (n - max_part)
        // using only parts less than max_part to ensure distinctness
        include := CountDP(n - max_part, max_part - 1, memo);
        exclude := CountDP(n, max_part - 1, memo);
        result := include + exclude;
      end if;
    end if;
  end if;

  memo[key] := result;
  return result;
end function;

